//- Macros constants

/** @brief: How many digits a test case number has. Two is plenty for the cases within one story.
 *
 * There is deliberately no matching constant for the story number: it is found by looking for the `_tc`
 * that follows it rather than by assuming how many digits came before, so `us101_tc01` reads the same as
 * `us06_tc03`. */
#define TC_ID_LEN (2)

/** @brief: Longest story number this will read, in digits. */
#define US_ID_MAX_DIGITS (6)

/** @brief: How many stories the suite has room for, and how many cases each may hold.
 *
 * Sized from the registry rather than guessed at: `NUM_USER_STORIES` is the number of story files that
 * exist plus one spare slot (so an empty registry still declares a non-empty array, which C requires).
 * `NUM_TC_PER_US` is a bound on how many cases one story may register, not a measurement, and exceeding
 * it is refused rather than tolerated. */
#define NUM_USER_STORIES (TESTSUITE_USER_STORY_COUNT + 1)
#define NUM_TC_PER_US (16)

//- Type definitions

typedef struct TestCase {
  uint32_t tc_id;/// @brief: Id of the test case.
  uint32_t us_id;/// @brief: UserStory id which this test case belongs to.
  const char *function_name;
  const char *acceptance_criteria;
  TestSignature callback;
  bool critical;
  uint32_t line_definition;// Which line this TestCase was defined
} TestCase;

typedef struct UserStory {
  uint32_t id;
  const char *us_name;
  const char *file_path;

  /* Wall-clock microseconds this story's cases have taken, accumulated rather than assigned.
   *
   * Accumulated because a story does not necessarily run all at once: its critical cases go in the
   * first pass and the rest in the second, so assigning here would record only the half that finished
   * last. */
  uint64_t elapsed_us;

  TestCase test_cases[NUM_TC_PER_US];
  uint32_t registered;
} UserStory;


typedef struct {
  char *stdout_buf;
  size_t stdout_size;
  FILE *stdout_fd_new;
  FILE *stdout_fd_original;
} OutputCapture;

typedef struct {
  TestCase *test_case;
  UserStory *user_story;
  OutputCapture test_output;
  int return_code;
} TestReport;


//- Private globals

static size_t user_story_count = 0;

/* The stories themselves, on the heap rather than a static: taken once, on first use, and kept for the
 * lifetime of the program. */
static UserStory *user_stories = NULL;

/* What was actually allocated for the table above, and nothing else. Recorded at the moment of the
 * allocation rather than derived from `user_stories != NULL`, because the question this answers is *how
 * big*, and a pointer being set is no evidence of that. */
static size_t stories_heap_bytes = 0;

static size_t test_reports_count = 0;

/* One report per case that runs. Taken once, on first use, and kept: nothing resets between stories. */
static TestReport *test_reports = NULL;

static size_t test_failures_count = 0;

/* Set when a critical case fails, which ends the run without ending the process. */
static bool _aborted = false;

