//- Private function implementation

/* Wraps malloc with the one thing plain malloc does not say on failure: what the memory was for. */
static void *_take(size_t bytes, const char *purpose) {
  if (bytes == 0) {
    return NULL;
  }
  void *buffer = malloc(bytes);
  if (buffer == NULL) {
    log_fail("No memory for %zu bytes of %s.", bytes, purpose);
  }
  return buffer;
}

/* Where a case's private, already-created scratch directory lives. TESTSUITE_TMP_DIR overrides the
 * default of /tmp/testsuite, for a run that wants its temporary files somewhere specific. */
static const char *_proj_tmp(void) {
  static char buff[256] = { 0 };
  if (buff[0] == '\0') {
    const char *env = getenv("TESTSUITE_TMP_DIR");
    snprintf(buff, sizeof(buff), "%s", (env != NULL) ? env : "/tmp/testsuite");
    _mkdir_p(buff);
  }
  return buff;
}

/* Where each story's captured output is written. TESTSUITE_OUTPUT_DIR overrides the default of
 * build/tests, relative to the current working directory. */
static const char *_output_root(void) {
  static char buff[256] = { 0 };
  if (buff[0] == '\0') {
    const char *env = getenv("TESTSUITE_OUTPUT_DIR");
    snprintf(buff, sizeof(buff), "%s", (env != NULL) ? env : "build/tests");
  }
  return buff;
}

static void _mkdir_p(const char *path) {
  char tmp[256];
  const int written = snprintf(tmp, sizeof(tmp), "%s", path);
  if (written < 0 || (size_t)written >= sizeof(tmp)) {
    log_fail("Path too long to create: \"%s\".", path);
    return;
  }

  size_t len = strlen(tmp);
  if (len > 0 && tmp[len - 1] == '/') {
    tmp[len - 1] = '\0';
  }

  for (char *p = tmp + 1; *p; ++p) {
    if (*p == '/') {
      *p = '\0';
      mkdir(tmp, 0755);
      *p = '/';
    }
  }
  mkdir(tmp, 0755);
}

static bool _dir_exists(const char *path) {
  struct stat st;
  return (stat(path, &st) == 0) && S_ISDIR(st.st_mode);
}

static int _unlink_cb(const char *fpath, const struct stat *sb, int typeflag, struct FTW *ftwbuf) {
  (void)sb;
  (void)typeflag;
  (void)ftwbuf;
  return remove(fpath);
}

static void _rmdir_r(const char *path) {
  nftw(path, _unlink_cb, 64, FTW_DEPTH | FTW_PHYS);
}

static const char *_basename(const char *path) {
  const char *last = strrchr(path, '/');
  return (last != NULL) ? last + 1 : path;
}

static bool _starts_with(const char *str, const char *prefix) {
  return strncmp(str, prefix, strlen(prefix)) == 0;
}

static uint32_t _parse_num(const char *str, size_t size) {
  uint32_t num = 0;
  for (size_t i = 0; i < size; ++i) {
    if (str[i] < '0' || str[i] > '9') {
      log_halt("Couldn't extract digit from \"%.*s\".", (int)size, str);
    }
    num = num * 10 + (uint32_t)(str[i] - '0');
  }
  return num;
}

/* The story table, allocated on first use.
 *
 * Unlike the reports, there is no carrying on without this one: it is where registration puts the
 * stories, so a suite that cannot have it has nothing to run and nothing to say about why. */
static UserStory *_stories(void) {
  if (user_stories == NULL) {
    const size_t bytes = sizeof(UserStory) * NUM_USER_STORIES;
    user_stories = (UserStory *)_take(bytes, "the suite's stories");
    if (user_stories != NULL) {
      stories_heap_bytes = bytes;
    }
  }
  return user_stories;
}

/* The report table, allocated on first use. Returns NULL if it could not be allocated, which the callers
 * treat as "no report to fill in" rather than falling over -- a suite that cannot record its results
 * should still run them. */
static TestReport *_reports(void) {
  if (test_reports == NULL) {
    test_reports = (TestReport *)_take(sizeof(TestReport) * NUM_USER_STORIES * NUM_TC_PER_US, "the suite's reports");
  }
  return test_reports;
}

static int _compare_user_stories(const void *a, const void *b) {
  const UserStory *lhs = (const UserStory *)a;
  const UserStory *rhs = (const UserStory *)b;
  if (lhs->id < rhs->id) return -1;
  if (lhs->id > rhs->id) return 1;
  return 0;
}

static int _compare_test_cases(const void *a, const void *b) {
  const TestCase *lhs = (const TestCase *)a;
  const TestCase *rhs = (const TestCase *)b;
  if (lhs->tc_id < rhs->tc_id) return -1;
  if (lhs->tc_id > rhs->tc_id) return 1;
  return 0;
}

static int _compare_test_report(const void *a, const void *b) {
  const TestReport *lhs = a;
  const TestReport *rhs = b;

  const UserStory *lhs_us = lhs->user_story;
  const UserStory *rhs_us = rhs->user_story;

  const TestCase *lhs_tc = lhs->test_case;
  const TestCase *rhs_tc = rhs->test_case;

  // [ ret  ] [spare ] [  us  ] [  tc  ]
  // 00000000 00000000 00000000 00000000

  uint32_t lhs_weight = ((lhs->return_code != 0) << 24) | (0 << 16) | (lhs_us->id << 8) | (lhs_tc->tc_id << 0);
  uint32_t rhs_weight = ((rhs->return_code != 0) << 24) | (0 << 16) | (rhs_us->id << 8) | (rhs_tc->tc_id << 0);

  if (lhs_weight < rhs_weight) return -1;
  if (lhs_weight > rhs_weight) return 1;
  return 0;
}

static int _capture_begin(OutputCapture *cap) {
  cap->stdout_buf = NULL;
  cap->stdout_size = 0;

  cap->stdout_fd_new = open_memstream(&cap->stdout_buf, &cap->stdout_size);
  cap->stdout_fd_original = stdout;

  stdout = cap->stdout_fd_new;
  return 0;
}

static void _capture_end(OutputCapture *cap) {
  fflush(cap->stdout_fd_new);
  stdout = cap->stdout_fd_original;
  fclose(cap->stdout_fd_new);
}

static void _capture_free(OutputCapture *cap) {
  free(cap->stdout_buf);
  cap->stdout_buf = NULL;
  cap->stdout_size = 0;
  cap->stdout_fd_new = NULL;
  cap->stdout_fd_original = NULL;
}

// Where the '_tc' sits in a name like 'us06_tc03' or 'us101_tc01'.
//
// Found rather than assumed, so a story number past 99 still reads correctly.
static const char *_find_tc(const char *fnName) {
  const char *at = strstr(fnName, "_tc");
  if (at == NULL) {
    log_halt("Test case \"%s\" has invalid format. Expected the name to contain '_tc'.", fnName);
  }
  return at;
}

static uint32_t _extract_us_id(const char *fnName) {
  // Example input: 'us06_tc03'
  if (!_starts_with(fnName, "us")) {
    log_halt("Test case \"%s\" has invalid format. Expected function name to start with 'us'.", fnName);
  }

  const char *digits = &fnName[2];
  const size_t length = (size_t)(_find_tc(fnName) - digits);

  if (length == 0 || length > US_ID_MAX_DIGITS) {
    log_halt("Test case \"%s\" has invalid format. Expected digits between 'us' and '_tc'.", fnName);
  }

  return _parse_num(digits, length);
}

static uint32_t _extract_tc_id(const char *fnName) {
  // Example input: 'us06_tc03'
  const char *tc = _find_tc(fnName);
  return _parse_num(tc + (sizeof("_tc") - 1), TC_ID_LEN);
}

static TestCase _create_test_case(
  const char *fnName,
  TestSignature testCb,
  const char *acceptanceCriteria,
  bool isCritical,
  uint32_t lineNum
) {
  uint32_t us_id = _extract_us_id(fnName);
  uint32_t tc_id = _extract_tc_id(fnName);
  log_misc(100, "From TestCase '%s' us_id=%u was extracted.", fnName, us_id);

  TestCase test_case = {
    .us_id = us_id,
    .tc_id = tc_id,
    .function_name = fnName,
    .acceptance_criteria = acceptanceCriteria,
    .callback = testCb,
    .critical = isCritical,
    .line_definition = lineNum,
  };

  return test_case;
}

static void _initialize_user_story(UserStory *user_story, const char *filePath) {
  const char *filename = _basename(filePath);
  /* The digits at the front of the file name, however many there are -- '04_...' and '101_...' alike. */
  size_t digits = 0;
  while (filename[digits] >= '0' && filename[digits] <= '9' && digits < US_ID_MAX_DIGITS) {
    ++digits;
  }
  if (digits == 0) {
    log_halt("Test file \"%s\" has invalid format. Expected it to start with the story number.", filename);
  }

  uint32_t us_id = _parse_num(filename, digits);

  user_story->id = us_id;
  user_story->us_name = filename;
  user_story->file_path = filePath;
  memset(user_story->test_cases, 0, sizeof(user_story->test_cases));
  user_story->registered = 0;
}

/* Wall-clock microseconds, for measuring how long the suite takes. */
static uint64_t _wall_clock_us(void) {
  struct timespec now;
  if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
    return 0;
  }
  return ((uint64_t)now.tv_sec * 1000000ULL) + ((uint64_t)now.tv_nsec / 1000ULL);
}

static void _execute_test_case(TestCase *testCase) {
  TestArguments test_args = { 0 };

  char test_tmp_dir[256] = { 0 };
  snprintf(test_tmp_dir, sizeof(test_tmp_dir), "%s/%s", _proj_tmp(), testCase->function_name);
  _mkdir_p(test_tmp_dir);
  test_args.tmp_dir = test_tmp_dir;

  log_misc(100, "Test \"%s\" will use \"%s\" as storage.", testCase->function_name, test_tmp_dir);

  log_base_raw(
    COLOR_WHITE "%s: " COLOR_SEAGREEN "%s" COLOR_DEFAULT "...", testCase->function_name, testCase->acceptance_criteria
  );

  TestReport *test_report = (_reports() != NULL) ? &_reports()[test_reports_count] : NULL;
  if (test_report == NULL) {
    log_fail("No memory for the suite's reports; cannot run `%s`.", testCase->function_name);
    return;
  }

  /* Start redirecting stdout/stderr */
  OutputCapture *cap = &test_report->test_output;
  _capture_begin(cap);

  /* A clean arena to work in: a case that borrows scratch should not find some of it already spent by
   * the case before. */
  _scratch_release();

  int test_result = testCase->callback(&test_args);

  _capture_end(cap);

  test_report->test_case = testCase;
  test_report->return_code = test_result;

  if (test_result == 0) {
    log_base(COLOR_GREEN " [SUCCESS]" COLOR_DEFAULT ".");
    _capture_free(cap);
  } else {
    ++test_failures_count;
    log_base(COLOR_RED " [FAILURE]" COLOR_DEFAULT " (Exit code: " COLOR_RED "%d" COLOR_DEFAULT ").", test_result);
    if (cap->stdout_size > 0) {
      log_base("\n" COLOR_WHITE "--------------- OUTPUT START ---------------" COLOR_DEFAULT);
      log_base_raw("%s", cap->stdout_buf);
      log_base(COLOR_WHITE "--------------- OUTPUT END   ---------------" COLOR_DEFAULT);
    } else {
      log_base("Test didn't emit any output.");
    }

    _capture_free(cap);

    if (testCase->critical) {
      log_fail(
        "Critical test failed: `%s`. Stopping here; nothing after it would mean anything.", testCase->function_name
      );
      _aborted = true;
    }
  }
}

/* Runs the cases of one story that belong to the phase being run.
 *
 * The header is printed lazily, only once something is actually about to run under it -- a story with
 * no critical cases must not leave an empty heading in the critical phase, which would be most of them.
 */
static void _execute_us_tests(UserStory *userStory, bool criticalPhase) {
  qsort(userStory->test_cases, userStory->registered, sizeof(userStory->test_cases[0]), _compare_test_cases);

  size_t in_phase = 0;
  for (size_t i = 0; i < userStory->registered; ++i) {
    if (userStory->test_cases[i].critical == criticalPhase) {
      ++in_phase;
    }
  }
  if (in_phase == 0) {
    return;
  }

  log_base("");
  log_base(COLOR_WHITE "--- Test Suite: %s ---" COLOR_DEFAULT, userStory->us_name);

  char output_dir[256] = { 0 };
  snprintf(output_dir, sizeof(output_dir), "%s/%s", _output_root(), userStory->us_name);
  if (_dir_exists(output_dir)) {
    _rmdir_r(output_dir);
  }
  _mkdir_p(output_dir);

  const uint64_t started = _wall_clock_us();

  for (size_t i = 0; i < userStory->registered; ++i) {
    TestCase *test_case = &userStory->test_cases[i];
    if (test_case->critical != criticalPhase) {
      continue;
    }
    if (_aborted) {
      return;
    }

    TestReport *test_report = (_reports() != NULL) ? &_reports()[test_reports_count] : NULL;
    if (test_report == NULL) {
      log_fail("No memory for the suite's reports; nothing will be recorded.");
      return;
    }
    test_report->user_story = userStory;

    _execute_test_case(test_case);
    ++test_reports_count;
  }

  userStory->elapsed_us += (_wall_clock_us() - started);
}

/* How long each story took, and the run as a whole. Printed in a form something else can read as well as
 * a person: `===TIMING===` is the prefix a script would grep for. */
static void _print_timings(const UserStory *stories, uint64_t totalUs) {
  /* Which stories the list below has already named, so it does not name one twice. */
  static size_t shown_already[5] = { 0 };

  log_base("");
  log_base(COLOR_WHITE "Slowest stories:" COLOR_DEFAULT);

  /* The five slowest, by inspection rather than by sorting a copy: this runs once at the end of a run. */
  for (int shown = 0; shown < 5; ++shown) {
    size_t slowest = user_story_count;
    uint64_t best = 0;

    for (size_t i = 0; i < user_story_count; ++i) {
      bool already = false;
      for (int j = 0; j < shown; ++j) {
        if (shown_already[j] == i) {
          already = true;
          break;
        }
      }
      if (!already && stories[i].elapsed_us >= best) {
        best = stories[i].elapsed_us;
        slowest = i;
      }
    }

    if (slowest >= user_story_count) {
      break;
    }
    shown_already[shown] = slowest;
    log_base("  %-44s %6llu ms", stories[slowest].us_name, (unsigned long long)(best / 1000ULL));
  }

  /* One line per story, for whatever wants to record them. Not pretty, and not meant to be. */
  for (size_t i = 0; i < user_story_count; ++i) {
    log_base_raw("===TIMING=== %s %llu\n", stories[i].us_name, (unsigned long long)stories[i].elapsed_us);
  }
  log_base_raw("===TIMING-TOTAL=== %llu\n", (unsigned long long)totalUs);
}

static void _print_test_report(void) {
  if (_reports() != NULL) {
    qsort(_reports(), test_reports_count, sizeof(TestReport), _compare_test_report);
  }

  log_base(COLOR_WHITE "==========================================================================" COLOR_DEFAULT);
  log_base(COLOR_WHITE "Test summary:" COLOR_DEFAULT);
  for (size_t i = 0; i < test_reports_count; ++i) {
    if (_reports() == NULL) {
      break;
    }
    const TestReport *test_report = &_reports()[i];

    const UserStory *user_story = test_report->user_story;
    const TestCase *test_case = test_report->test_case;

    bool test_passed = (test_report->return_code == 0);
    const char *file_path = user_story->file_path;

    const char *result = test_passed ? COLOR_GREEN "[SUCC]" COLOR_DEFAULT : COLOR_RED "[FAIL]" COLOR_DEFAULT;
    uint32_t line_num = test_passed ? test_case->line_definition : (uint32_t)test_report->return_code;
    const char *color = test_passed ? COLOR_SEAGREEN : COLOR_RED;

    log_base("%s %s[%s:%u]" COLOR_DEFAULT, result, color, file_path, line_num);
  }
  log_base(COLOR_WHITE "==========================================================================" COLOR_DEFAULT);
}

//- Public function implementation

void __add_test_case(
  UserStory *us,
  const char *fnName,
  TestSignature testCb,
  const char *acceptanceCriteria,
  bool isCritical,
  uint32_t lineNum
) {
  TestCase test_case = _create_test_case(fnName, testCb, acceptanceCriteria, isCritical, lineNum);
  if (test_case.us_id != us->id) {
    log_halt("Trying to register invalid function '%s' into UserStory id=%u", test_case.function_name, us->id);
  }
  if (us->registered >= NUM_TC_PER_US) {
    log_halt("No room for more test cases. Insertion of \"%s\" failed.", test_case.function_name);
  }

  us->test_cases[us->registered] = test_case;
  ++us->registered;
}

/* The arena itself, and how much of it this case has spent. */
static uint8_t *_scratch = NULL;
static size_t _scratch_used = 0;

/* Hands the whole arena back. Called by the case runner before each case, so the accounting is per case
 * rather than per run -- otherwise the first story to ask would spend it and the second would be
 * refused, which is precisely the bug a bump allocator invites if nobody resets it. */
static void _scratch_release(void) {
  _scratch_used = 0;
}

void *test_scratch(size_t bytes) {
  if (_scratch == NULL) {
    _scratch = (uint8_t *)_take(TEST_SCRATCH_MAX, "the suite's scratch");
    if (_scratch == NULL) {
      return NULL;
    }
  }

  if (bytes == 0) {
    log_fail("Asked for no test scratch at all.");
    return NULL;
  }

  /* Kept eight-byte aligned: a caller casting the result to a struct or a `uint32_t *` is entitled to
   * an aligned pointer. */
  const size_t aligned = (bytes + 7U) & ~(size_t)7U;

  if (aligned > TEST_SCRATCH_MAX - _scratch_used) {
    log_fail(
      "Asked for %zu bytes of test scratch; this case has %zu of %u left.",
      bytes,
      TEST_SCRATCH_MAX - _scratch_used,
      TEST_SCRATCH_MAX
    );
    return NULL;
  }

  uint8_t *out = _scratch + _scratch_used;
  _scratch_used += aligned;

  /* Handed out clean on every call, not merely at start-up: a builder that writes a header and a body
   * leaves the gaps between them untouched otherwise, and a reused buffer carries the last case's
   * leavings into them. */
  memset(out, 0, aligned);

  return out;
}

size_t test_registered_user_stories(void) {
  return user_story_count;
}

size_t test_stories_heap_bytes(void) {
  return stories_heap_bytes;
}

UserStory *__get_next_user_story(const char *fileName) {
  UserStory *stories = _stories();
  if (stories == NULL) {
    log_halt("No memory for the suite's stories; there is nothing to register into.");
  }

  if (user_story_count >= NUM_USER_STORIES) {
    log_halt("Failed to fetch next user story. Reached the array limit.");
  }

  UserStory *user_story = &stories[user_story_count];
  ++user_story_count;

  _initialize_user_story(user_story, fileName);
  user_story->elapsed_us = 0;

  return user_story;
}

int test_user_stories(void) {
  UserStory *stories = _stories();
  if (stories == NULL || user_story_count == 0) {
    log_fail("No stories registered; there is nothing to run.");
    return 1;
  }

  qsort(stories, user_story_count, sizeof(stories[0]), _compare_user_stories);

  const uint64_t run_started = _wall_clock_us();
  _aborted = false;

  /* Two passes: everything marked critical, then everything else.
   *
   * When something fundamental breaks -- the framework itself, the one thing everything else is built
   * on -- every case downstream of it fails too, and running in file order buries the one useful line in
   * the middle of a report about its consequences. Ordering by a flag instead means the report is no
   * longer in file order, so it says which pass it is in. */
  log_base("");
  log_base(COLOR_WHITE "=== Critical cases: if one of these fails, nothing after it means anything ===" COLOR_DEFAULT);

  for (size_t i = 0; i < user_story_count && !_aborted; ++i) {
    _execute_us_tests(&stories[i], true);
  }

  if (!_aborted) {
    log_base("");
    log_base(COLOR_WHITE "=== Everything else ===" COLOR_DEFAULT);

    for (size_t i = 0; i < user_story_count && !_aborted; ++i) {
      _execute_us_tests(&stories[i], false);
    }
  }

  log_base("\n");
  _print_test_report();
  _print_timings(stories, _wall_clock_us() - run_started);

  if (_aborted) {
    log_fail("The run stopped early: a critical case failed, so the cases after it were not run.");
  }

  return (int)test_failures_count;
}

bool test_run_aborted(void) {
  return _aborted;
}

size_t test_registered_case_count(void) {
  size_t total = 0;
  UserStory *stories = _stories();
  if (stories == NULL) {
    return 0;
  }

  for (size_t i = 0; i < user_story_count; ++i) {
    total += stories[i].registered;
  }
  return total;
}

int test_critical_case_count(void) {
  int total = 0;
  UserStory *stories = _stories();
  if (stories == NULL) {
    return 0;
  }

  for (size_t i = 0; i < user_story_count; ++i) {
    for (size_t j = 0; j < stories[i].registered; ++j) {
      if (stories[i].test_cases[j].critical) {
        ++total;
      }
    }
  }
  return total;
}
